<?php
$jenis=$_GET['jenis']??'penjualan';
if($jenis==='produk'){$q=mysqli_query($conn,"SELECT b.*,COALESCE(t.nm_type,'-') AS nm_type FROM barang b LEFT JOIN `type` t ON t.id_type=b.id_type ORDER BY b.nm_brg");}
else{$q=mysqli_query($conn,"SELECT fj.*,COALESCE(m.nm_member,'-') AS nm_member,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(b.nm_brg,' (',COALESCE(dj.ukuran,'M'),')') ORDER BY b.nm_brg SEPARATOR ', '),'-') AS produk FROM faktur_jual fj LEFT JOIN member m ON m.id_member=fj.id_member LEFT JOIN detal_jual dj ON dj.no_faktur=fj.no_faktur LEFT JOIN barang b ON b.id_brg=dj.id_brg GROUP BY fj.id_faktur,fj.no_faktur,fj.id_member,fj.tgl_faktur,fj.total,fj.status,fj.order_status,fj.catatan_admin,fj.tgl_approve,fj.tgl_order ORDER BY fj.tgl_order DESC");}
?>
