<?php if($jenis==='produk'):?><thead><tr><th>No</th><th>Produk</th><th>Type</th><th>Harga</th><th>Stok</th></tr></thead><tbody><?php $n=1;while($r=mysqli_fetch_assoc($q)):?><tr class="data-row"><td><?php echo $n++;?></td><td><b><?php echo e($r['nm_brg']);?></b></td><td><?php echo e($r['nm_type']);?></td><td><?php echo rupiah($r['hrg_jual']);?></td><td><?php echo (int)$r['stok'];?></td></tr><?php endwhile;?></tbody>
<?php else: ?><thead><tr><th>No</th><th>Tanggal</th><th>No Pesanan</th><th>Pelanggan</th><th>Produk</th><th>Total</th><th>Status</th></tr></thead><tbody><?php $n=1;while($r=mysqli_fetch_assoc($q)): $s=$r['order_status'];?><tr class="data-row"><td><?php echo $n++;?></td><td><?php echo e(date('d M Y',strtotime($r['tgl_order'])));?></td><td><?php echo e($r['no_faktur']);?></td><td><?php echo e($r['nm_member']);?></td><td><?php echo e($r['produk']);?></td><td><?php echo rupiah($r['total']);?></td><td><?php echo e(order_status_label($s));?></td></tr><?php endwhile;?></tbody><?php endif;?></table></div></div>